import{_ as s,o as n,c as e,ai as i}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"业务系统里的 AI 切口","description":"","frontmatter":{},"headers":[],"relativePath":"ai/app/enterprise/biz-entry.md","filePath":"ai/app/enterprise/biz-entry.md"}'),p={name:"ai/app/enterprise/biz-entry.md"};function r(l,a,t,h,o,d){return n(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="业务系统里的-ai-切口" tabindex="-1">业务系统里的 AI 切口 <a class="header-anchor" href="#业务系统里的-ai-切口" aria-label="Permalink to “业务系统里的 AI 切口”">​</a></h1><p>原文就一句话：优先选高频、重复、规则相对清楚的环节。下面把这句话展开成判断标准——<strong>什么地方值得接 AI，什么地方不值得接，以及 AI 应该怎么进原有业务流程。</strong></p><p>这不是企业 AI 场景大全，也不是项目交付报告。</p><hr><h2 id="为什么不是所有业务都适合接-ai" tabindex="-1">为什么不是所有业务都适合接 AI <a class="header-anchor" href="#为什么不是所有业务都适合接-ai" aria-label="Permalink to “为什么不是所有业务都适合接 AI”">​</a></h2><p>传统业务系统擅长的事情很明确：规则、确定性计算、存数据、走状态、控权限、管事务。这些本来就不该让模型去「猜」。</p><p>模型更擅长另一类工作：读一段说明、抽关键信息、做摘要、给分类建议、按资料回答问题、用自然语言当入口。</p><p>所以：</p><blockquote><p><strong>AI 不应该替代整个业务系统，而应该进入流程里适合它的那一截。</strong></p></blockquote><p>把整套 CRM / OA 换成聊天框，通常不是落地，是把确定性工作重新变回不确定。</p><hr><h2 id="我怎么判断一个场景值不值得接" tabindex="-1">我怎么判断一个场景值不值得接 <a class="header-anchor" href="#我怎么判断一个场景值不值得接" aria-label="Permalink to “我怎么判断一个场景值不值得接”">​</a></h2><h3 id="_1-有没有大量信息处理" tabindex="-1">1. 有没有大量信息处理 <a class="header-anchor" href="#_1-有没有大量信息处理" aria-label="Permalink to “1. 有没有大量信息处理”">​</a></h3><p>文档、制度、工单描述、申请说明、沟通记录——人读得慢、抄得烦的地方，模型才有用武之地。如果输入已经是几个下拉框和数字，传统校验就够了。</p><h3 id="_2-有没有明确业务目标" tabindex="-1">2. 有没有明确业务目标 <a class="header-anchor" href="#_2-有没有明确业务目标" aria-label="Permalink to “2. 有没有明确业务目标”">​</a></h3><p>「让 AI 帮忙」不算目标。比较像样的说法是：某类申请先被压缩成可读的摘要；某类工单先分到正确队列；制度问题先给出带来源的草稿。目标越具体，后面越好验收。</p><h3 id="_3-能不能人工复核" tabindex="-1">3. 能不能人工复核 <a class="header-anchor" href="#_3-能不能人工复核" aria-label="Permalink to “3. 能不能人工复核”">​</a></h3><p>我更认这条链：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AI 建议 → 人工确认 → 业务系统执行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>而不是：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AI → 直接改库 / 直接过审</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>人复核不是保守，是把错误拦在不可逆之前。</p><h3 id="_4-出错成本是否可控" tabindex="-1">4. 出错成本是否可控 <a class="header-anchor" href="#_4-出错成本是否可控" aria-label="Permalink to “4. 出错成本是否可控”">​</a></h3><p>低风险：摘要、分类建议、检索、辅助分析。<br> 高风险：财务拍板、自动审批、改核心数据、执行不可逆操作。</p><p>自动化程度要和错误成本匹配。错了能改、能回滚、能被人拦住的，才适合先上。</p><h3 id="_5-能不能嵌进已有流程" tabindex="-1">5. 能不能嵌进已有流程 <a class="header-anchor" href="#_5-能不能嵌进已有流程" aria-label="Permalink to “5. 能不能嵌进已有流程”">​</a></h3><p>单独做一个「AI 聊天页」，同事用两次就回去点原来的按钮。真正有用的是：原流程走到某一环，弹出 AI 处理，人点确认，系统接着走。</p><hr><h2 id="哪些场景可以优先看" tabindex="-1">哪些场景可以优先看 <a class="header-anchor" href="#哪些场景可以优先看" aria-label="Permalink to “哪些场景可以优先看”">​</a></h2><p>不必列十个。结合常见企业系统，我先看这几类：</p><p><strong>审批辅助。</strong> 总结申请、抽出金额/时限/异常点、提醒风险。过不过，仍是人点。</p><p><strong>工单辅助。</strong> 归纳问题、分类、抽关键字段、给处理建议。关单和改状态仍走原系统。</p><p><strong>企业知识问答。</strong> 按已有制度/手册回答，并带来源；答不上来就说不确定。没有资料就不要硬答。</p><p><strong>业务信息整理。</strong> 客户跟进摘要、会议纪要、从长文本里抽字段。本质是减阅读量。</p><p><strong>业务 Agent（概念上）。</strong> 从「回答问题」再往前一步：理解任务 → 调业务接口 → 得到结果 → 核对。这里只作为方向，不写成已经落地的产品。</p><p>原文里的审批摘要、工单分类、制度问答，仍然是我认为最顺的三个切口。</p><hr><h2 id="哪些地方先别急着接" tabindex="-1">哪些地方先别急着接 <a class="header-anchor" href="#哪些地方先别急着接" aria-label="Permalink to “哪些地方先别急着接”">​</a></h2><p><strong>规则已经写死的。</strong> 几行 if 就能算准的，不必为了 AI 而 AI。</p><p><strong>高风险且没法复核。</strong> 模型一判断就自动执行、无法撤回的，先不要接。</p><p><strong>没有上下文和数据。</strong> 没有制度、没有工单、没有历史记录，接模型多半只是聊天。</p><p><strong>收益盖不住维护。</strong> 费用、延迟、Prompt、评测、失败重试、权限，都要算进去。省不了人时间，就只是多一个不稳定环节。</p><hr><h2 id="ai-怎么进传统业务系统" tabindex="-1">AI 怎么进传统业务系统 <a class="header-anchor" href="#ai-怎么进传统业务系统" aria-label="Permalink to “AI 怎么进传统业务系统”">​</a></h2><p>更接近现实的形状是：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>用户</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>业务系统</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>业务上下文（当前单据、权限、制度、历史）</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>AI 能力</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>AI 结果</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>人工确认 / 规则校验</span></span>
<span class="line"><span> ↓</span></span>
<span class="line"><span>业务系统（写回、流转、落库）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><blockquote><p><strong>AI 是业务系统里的一个能力节点，不是整套系统。</strong></p></blockquote><p>我以前做 Java / 全栈企业系统，主要解决的是数据、流程、权限、状态、事务。模型能做的变化是：以前必须人先读懂的信息，可以先让它出一稿。但业务规则、最终决策、数据一致性和能不能上线，还是工程系统的责任。不是「AI 改变一切」，是信息处理这一段可以前移。</p><hr><h2 id="我的判断" tabindex="-1">我的判断 <a class="header-anchor" href="#我的判断" aria-label="Permalink to “我的判断”">​</a></h2><p>我更愿意把 AI 看成业务系统<strong>新增的一种能力</strong>，而不是再做一套并行的「AI 系统」。</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>传统系统：数据 + 规则 + 流程</span></span>
<span class="line"><span>接上 AI 之后：数据 + 规则 + 流程 + AI 能力 + 人工验证</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>高频、重复、规则边界清楚、出错可拦——这才是切口。看起来很炫、但一旦错了就伤数据或伤人的，先放一放。</p><hr><h2 id="关于本文" tabindex="-1">关于本文 <a class="header-anchor" href="#关于本文" aria-label="Permalink to “关于本文”">​</a></h2><p>本文是基于企业软件开发经验的判断和方案思考。审批、工单、知识问答等仍偏设计和探索，<strong>不代表已经在生产里大规模落地</strong>。没有项目名、没有准确率、没有省了多少人天——那些要等真做了再写。</p>`,56)])])}const g=s(p,[["render",r]]);export{b as __pageData,g as default};
